tool_input.command:
python3 - <<'EOF'
p='src/board.ts'
s=open(p).read()
i=s.index('export function createBoard')
s=s[:i]+'''interface Card {
  id: string;
  column: number;
  blockedReason: string | null;
  /** Blocked intervals; `end` is null while the card is still blocked. */
  blocks: { start: number; end: number | null }[];
  startedAt: number | null;
  finishedAt: number | null;
}

export function createBoard(options: BoardOptions): Board {
  const columns = options.columns.map((c) => ({ ...c }));
  const lists: string[][] = columns.map(() => []);
  const cards = new Map<string, Card>();
  const last = columns.length - 1;
  let nextId = 1;

  function getCard(cardId: string): Card {
    const card = cards.get(cardId);
    if (!card) throw new BoardError("UNKNOWN_CARD", `Unknown card ${cardId}`);
    return card;
  }

  function columnIndex(name: string): number {
    const index = columns.findIndex((c) => c.name === name);
    if (index < 0) throw new BoardError("UNKNOWN_COLUMN", `Unknown column ${name}`);
    return index;
  }

  function isFull(index: number): boolean {
    const limit = columns[index].wipLimit;
    return limit !== undefined && lists[index].length >= limit;
  }

  return {
    addCard(title) {
      if (title.trim() === "") throw new BoardError("EMPTY_TITLE", "Title must not be empty");
      if (isFull(0)) throw new BoardError("WIP_LIMIT", `Column ${columns[0].name} is full`);
      const id = `C${nextId++}`;
      cards.set(id, {
        id,
        column: 0,
        blockedReason: null,
        blocks: [],
        startedAt: null,
        finishedAt: null,
      });
      lists[0].push(id);
      return id;
    },

    move(cardId, toColumn) {
      const card = getCard(cardId);
      const to = columnIndex(toColumn);
      if (card.column === to) throw new BoardError("SAME_COLUMN", `Card ${cardId} is already in ${toColumn}`);
      if (card.blockedReason !== null) throw new BoardError("BLOCKED", `Card ${cardId} is blocked`);
      if (to > card.column + 1) throw new BoardError("SKIP_NOT_ALLOWED", `Card ${cardId} cannot skip columns`);
      if (isFull(to)) throw new BoardError("WIP_LIMIT", `Column ${toColumn} is full`);

      const now = options.now();
      const from = lists[card.column];
      from.splice(from.indexOf(cardId), 1);
      lists[to].push(cardId);
      if (card.column === 0 && card.startedAt === null) card.startedAt = now;
      if (to === last) card.finishedAt = now;
      card.column = to;
    },

    block(cardId, reason) {
      const card = getCard(cardId);
      if (card.blockedReason !== null) throw new BoardError("ALREADY_BLOCKED", `Card ${cardId} is already blocked`);
      card.blockedReason = reason;
      card.blocks.push({ start: options.now(), end: null });
    },

    unblock(cardId) {
      const card = getCard(cardId);
      if (card.blockedReason === null) throw new BoardError("NOT_BLOCKED", `Card ${cardId} is not blocked`);
      card.blockedReason = null;
      card.blocks[card.blocks.length - 1].end = options.now();
    },

    cardsIn(column) {
      return [...lists[columnIndex(column)]];
    },

    cycleTime(cardId) {
      const card = getCard(cardId);
      if (card.column !== last || card.startedAt === null || card.finishedAt === null) return null;
      const started = card.startedAt;
      const finished = card.finishedAt;
      let blockedMs = 0;
      let now: number | undefined;
      for (const block of card.blocks) {
        const end = block.end ?? (now ??= options.now());
        const overlap = Math.min(end, finished) - Math.max(block.start, started);
        if (overlap > 0) blockedMs += overlap;
      }
      return { totalMs: finished - started, blockedMs };
    },
  };
}
'''
open(p,'w').write(s)
EOF
